CartExtension.CartCalculateExecutorMock calc = new CartExtension.CartCalculateExecutorMock();
CartExtension.CartCalculateCalculatorRequest req = new CartExtension.CartCalculateCalculatorRequest(null, null);
calc.calculate(new CartExtension.CartCalculateOrchestratorRequest(null, null, null));
calc.defaultInventory(req);
calc.defaultPrices(req);
calc.defaultPromotions(req);
calc.defaultShipping(req);
calc.defaultTax(req);
calc.inventory(req);
calc.postShipping(req);
calc.prices(req);
calc.promotions(req);
calc.shipping(req);
calc.tax(req);
String calcJson = JSON.serialize(calc);
System.assert(calcJson.contains('"callCount":12'));
System.assert(calcJson.contains('"lastMethod":"tax"'));
System.assert(calcJson.contains('"lastArgs"'));
CartExtension.PricingCartCalculator pricing = new CartExtension.PricingCartCalculator(calc);
pricing.calculate(req);
String backedJson = JSON.serialize(calc);
System.assert(backedJson.contains('"callCount":13'));
System.assert(backedJson.contains('"lastMethod":"prices"'));
CartExtension.SplitShipmentServiceMock splitMock = new CartExtension.SplitShipmentServiceMock();
splitMock.arrangeItems(null);
String splitJson = JSON.serialize(splitMock);
System.assert(splitJson.contains('"callCount":1'));
System.assert(splitJson.contains('"lastMethod":"arrangeItems"'));
CartExtension.SplitShipmentService split = new CartExtension.SplitShipmentService(splitMock);
split.arrangeItems(null);
String backedSplitJson = JSON.serialize(splitMock);
System.assert(backedSplitJson.contains('"callCount":2'));
System.assert(backedSplitJson.contains('"lastMethod":"arrangeItems"'));

